function navigateTo(page) {
    document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
    const target = document.getElementById('page-' + page);
    if (target) target.classList.add('active');
    document.querySelectorAll('.nav-links a').forEach(a => a.classList.toggle('active', a.getAttribute('data-page') === page));
    document.getElementById('navLinks').classList.remove('open');
    window.scrollTo({ top: 0, behavior: 'smooth' });
    if (page === 'colleges') renderCollegesList();
    if (page === 'scholarships') renderScholarships();
    if (page === 'deadlines') renderDeadlines();
    if (page === 'admin') populateAdminCollegeSelect();
}
function toggleMobileNav() { document.getElementById('navLinks').classList.toggle('open'); }

// MATCHING ENGINE
function calculateMatchScore(college, courseObj, profile) {
    let score = 0, maxScore = 0, reasons = [];
    maxScore += 25;
    if (courseObj.name === profile.course) { score += 25; reasons.push({text:"Strong course match",type:"good"}); }
    else if (courseObj.name.toLowerCase().includes(profile.course.toLowerCase().split(' ')[0])) { score += 12; reasons.push({text:"Related course",type:"ok"}); }
    else { reasons.push({text:"Different course",type:"neutral"}); }
    maxScore += 20;
    if (profile.marks >= courseObj.eligibility) { score += 20; reasons.push({text:"Eligibility met",type:"good"}); }
    else { const d = courseObj.eligibility - profile.marks; if (d <= 5) { score += 8; reasons.push({text:"Close to eligibility",type:"ok"}); } else { reasons.push({text:"Below eligibility",type:"neutral"}); } }
    maxScore += 25;
    if (courseObj.fee <= profile.budget) { score += 25; reasons.push({text:"Within budget",type:"good"}); }
    else { const o = courseObj.fee - profile.budget; if (o <= 30000) { score += 10; reasons.push({text:"Slightly over budget",type:"ok"}); } else { reasons.push({text:"Over budget",type:"neutral"}); } }
    maxScore += 15;
    if (profile.location === "Any" || profile.location === college.location) { score += 15; if (profile.location !== "Any") reasons.push({text:"Preferred location",type:"good"}); }
    else { reasons.push({text:"Different location",type:"neutral"}); }
    maxScore += 10;
    if (profile.entranceScore) { if (profile.entranceScore >= 70) { score += 10; reasons.push({text:"Strong entrance score",type:"good"}); } else if (profile.entranceScore >= 50) { score += 5; reasons.push({text:"Moderate entrance score",type:"ok"}); } else { reasons.push({text:"Low entrance score",type:"neutral"}); } } else { score += 5; }
    maxScore += 5;
    if (courseObj.availableSeats > 0) { score += 5; reasons.push({text:"Reported seats available",type:"good"}); } else { reasons.push({text:"No reported seats",type:"neutral"}); }
    return { percentage: Math.round((score / maxScore) * 100), reasons };
}
function findMatches(profile) {
    const results = [];
    COLLEGES.forEach(college => { college.courses.forEach(courseObj => { const m = calculateMatchScore(college, courseObj, profile); results.push({college, course:courseObj, matchScore:m.percentage, reasons:m.reasons}); }); });
    results.sort((a, b) => b.matchScore - a.matchScore);
    return results;
}

// FORM
function handleProfileSubmit(e) {
    e.preventDefault();
    const profile = { name: document.getElementById('studentName').value, marks: parseInt(document.getElementById('marks').value), entranceScore: parseInt(document.getElementById('entranceScore').value) || null, course: document.getElementById('course').value, location: document.getElementById('location').value, budget: parseInt(document.getElementById('budget').value), admissionRoute: document.getElementById('admissionRoute').value || null };
    currentUserProfile = profile;
    currentResults = findMatches(profile);
    document.getElementById('resultsSummary').textContent = `Showing ${currentResults.length} opportunities for ${profile.name} — ${profile.course} in ${profile.location === 'Any' ? 'any location' : profile.location}`;
    renderResults();
    navigateTo('results');
}

// RESULTS
function renderResults() {
    const c = document.getElementById('resultsContainer'), nr = document.getElementById('noResults');
    if (!currentResults.length) { c.style.display='none'; nr.style.display='block'; return; }
    c.style.display='grid'; nr.style.display='none';
    c.innerHTML = currentResults.map((r, i) => {
        const {college, course, matchScore, reasons} = r;
        const s = getStatusClass(college.lastUpdated), sl = getStatusLabel(college.lastUpdated, college.verificationStatus);
        return `<div class="result-card ${i===0?'top-match':''}"><div class="result-main"><div class="result-header"><div><div class="result-college-name">${college.name}</div><div class="result-location">📍 ${college.location}</div></div><div class="result-match"><div class="match-percentage">${matchScore}%</div><div class="match-label">Match</div></div></div><div class="result-tags">${reasons.map(r=>`<span class="match-tag ${r.type}">${r.type==='good'?'✓':r.type==='ok'?'~':'○'} ${r.text}</span>`).join('')}</div><div style="margin-top:0.5rem;"><span style="font-weight:600;color:var(--primary);font-size:0.95rem;">${course.name}</span></div><div class="result-meta"><span>💰 ₹${(course.fee/10000).toFixed(1)} lakh/year</span><span>💺 ${course.availableSeats} reported seats</span><span>📊 Eligibility: ${course.eligibility}%</span></div><div class="result-updated">Last updated: ${formatDate(college.lastUpdated)}</div><div style="display:flex;align-items:center;gap:0.5rem;margin-top:0.25rem;"><span class="status-badge ${s}">${sl}</span>${college.verificationStatus==='verified'?'<span class="status-badge green">✓ Verified</span>':'<span class="status-badge yellow">⏳ Needs Verification</span>'}</div><div class="result-actions"><button class="btn btn-primary btn-sm" onclick="viewCollegeDetail(${college.id},'${course.name}')">View Details</button><button class="btn btn-outline btn-sm" onclick="openChecklistModal(${college.id})">📋 Checklist</button><button class="btn btn-outline btn-sm" onclick="navigateTo('scholarships')">Scholarship Options</button></div></div></div>`;
    }).join('');
}
function sortResults() {
    const v = document.getElementById('sortResults').value;
    if (v==='match') currentResults.sort((a,b)=>b.matchScore-a.matchScore);
    else if (v==='fee') currentResults.sort((a,b)=>a.course.fee-b.course.fee);
    else if (v==='seats') currentResults.sort((a,b)=>b.course.availableSeats-a.course.availableSeats);
    renderResults();
}

